use std::collections::HashSet;

/// Removes duplicates from the input vector of i32 integers,
/// returning a new vector that contains the same elements but without duplicates.
/// - The output vector contains no duplicates.
/// - The set of elements in the output equals the set of elements in the input.
///
/// Elements preserve their first-occurrence order.
///
fn remove_duplicates(nums: Vec<i32>) -> Vec<i32> {
    let mut seen = HashSet::new();
    let mut res = Vec::new();
    for &num in nums.iter() {
        if seen.insert(num) {
            // insert returns true if num was not already present
            res.push(num);
        }
    }
    res
}

